root <- normalizePath(".", mustWork=TRUE); files <- c("preprocessing_config.R","preprocessing_validation.R","preprocessing_observations.R","preprocessing_spatial.R","preprocessing_covariates.R","preprocessing_transformations.R","preprocessing_outputs.R"); for (f in files) source(file.path(root,"R",f))
cfg <- list(project=list(seed=1976,output_directory=file.path(root,"outputs/preprocessing_demo")),study=list(start_date="2022-01-01",end_date="2022-03-31",projected_crs="EPSG:4326"),transformations=list(temperature_hinge=12),tier1_thinning=list(enabled=FALSE,seed=1976)); dir.create(cfg$project$output_directory,recursive=TRUE,showWarnings=FALSE); set.seed(cfg$project$seed)
boundary <- sf::st_as_sf(sf::st_sfc(sf::st_polygon(list(rbind(c(-100,10),c(-80,10),c(-80,25),c(-100,25),c(-100,10)))),crs=4326)); obs <- data.frame(date=as.Date("2022-01-01")+sample(0:80,30,TRUE),lon=runif(30,-99,-81),lat=runif(30,11,24),host=sample(c("bovine","equine","unknown","bovino-equino"),30,TRUE)); lookup <- data.frame(host_cleaned=c("bovine","equine","unknown","bovinoequino"),host_standardized=c("bovine","equine","unknown","bovine"),host_group=c("livestock","livestock","unknown","livestock"),multiple_host_flag=c(FALSE,FALSE,FALSE,TRUE)); cleaned <- preprocess_observations(obs,boundary,cfg,lookup); support <- build_spatial_support(boundary,cleaned$data,cfg); time <- make_week_index(cfg$study$start_date,cfg$study$end_date); t1 <- build_tier1(cleaned$data,support$integration_points,time); t2 <- build_tier2(cleaned$data,support,time); pred <- build_prediction_grid(support,time); for (nm in c("mintemp","soilmoist","leafarea","rhum","cattle","horses","pigs","sheep","goats","road_density","night_illumination")) { t1[[nm]] <- 1; t2[[nm]] <- 1; pred[[nm]] <- 1 }; tr <- estimate_transformations(t2,cfg); out <- assemble_model_inputs(apply_transformations(t1,tr,FALSE),apply_transformations(t2,tr),apply_transformations(pred,tr),support,time,tr,list(observation=cleaned$audit,covariate=data.frame()),cfg); saveRDS(out,file.path(cfg$project$output_directory,"model_inputs.rds")); write.csv(cleaned$audit,file.path(cfg$project$output_directory,"observation_audit.csv"),row.names=FALSE); message("Demo complete: ",nrow(t1)," Tier 1 rows, ",nrow(t2)," Tier 2 rows, ",nrow(pred)," prediction rows")
